[IO.File]::WriteAllText((Join-Path $PWD 'peak.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh peak.sh PORT GLOB [curl options]`n# Serves site with every answer held 1 s, so transfers that run together overlap; fetches GLOB`n# with the given curl options; then reads surl's trace and prints the most connections open at`n# once and the most requests being answered at once.`nport=`$1; glob=`$2; shift 2`nrm -f trace.txt listening.txt`nsurl --directory site --fault `"delay;stage=command;ms=1000`" --trace-ascii trace.txt http://127.0.0.1:`$port/ >listening.txt 2>/dev/null &`npid=`$!`nuntil grep -q Listening listening.txt; do sleep 0.1; done`ncurl -s `"`$@`" `"http://127.0.0.1:`$port/`$glob`"`n# curl has exited: wait (at most 10 s) until surl has seen every connection close.`ntries=0`nwhile [ `"`$(grep -c ' ended; closing' trace.txt)`" != `"`$(grep -c ' opened: ' trace.txt)`" ] && [ `$tries -lt 100 ]; do`n  sleep 0.1; tries=`$((tries + 1))`ndone`nkill `$pid`nwait `$pid 2>/dev/null`nawk '/ opened: / { n++; if (n > peak) peak = n } / ended; closing/ { n-- } END { print `"connections`", peak + 0 }' trace.txt`nawk '/held for/ { n++; if (n > peak) peak = n } / \* GET .*: 200/ { n-- } END { print `"requests`", peak + 0 }' trace.txt`n")
sh peak.sh 8080 "f[1-12].txt" --parallel --parallel-max 4 --create-dirs -o "got/f#1.txt"
